package com.liujyks.trainflow.core.data

import android.util.JsonWriter
import com.liujyks.trainflow.core.database.CanonicalJsonValue
import com.liujyks.trainflow.core.database.CanonicalSessionGraphV1
import com.liujyks.trainflow.core.database.StatusProjectionV1
import com.liujyks.trainflow.core.database.entity.HeartRateAnalysisSnapshotEntity
import com.liujyks.trainflow.core.database.entity.HeartRateRecordingEntity
import com.liujyks.trainflow.core.database.entity.WorkoutSessionEntity
import com.liujyks.trainflow.core.database.parseCanonicalJson
import com.liujyks.trainflow.core.model.RepTarget
import com.liujyks.trainflow.core.model.WeightValue
import java.io.Writer
import java.time.Instant
import java.time.LocalDate
import java.time.format.DateTimeFormatterBuilder

internal data class WorkoutSessionExportSelection(
    val source: String,
    val startDateInclusive: LocalDate?,
    val endDateInclusive: LocalDate?,
    val modeFilter: Set<String>?,
    val planFilter: Set<String>?,
    val includedSessionIds: List<String>,
    val includedUnknownDateSessionIds: List<String>
)

internal class WorkoutSessionExportReadRejected(
    val requestedSessionId: String,
    val source: WorkoutSessionStrictReadResult
) : IllegalStateException("Strict session read failed for $requestedSessionId")

internal class WorkoutSessionExportHistoricalRejected(
    val requestedSessionId: String,
    val source: WorkoutSessionHistoricalResult
) : IllegalStateException("Historical resolution failed for $requestedSessionId")

/** One instance writes one Export v2 document. The caller owns the underlying Writer. */
internal class WorkoutSessionExport(
    output: Writer,
    private val selection: WorkoutSessionExportSelection,
    generatedAt: Instant,
    private val displayLocale: String
) {
    private val json = JsonWriter(output)
    private var nextSession = 0
    private var finished = false

    init {
        require(selection.source == "single_session" || selection.source == "calendar") { "selection.source" }
        require(selection.includedSessionIds.isNotEmpty() &&
            selection.includedSessionIds.size == selection.includedSessionIds.toSet().size) { "selection.includedSessionIds" }
        require((selection.startDateInclusive == null) == (selection.endDateInclusive == null)) { "selection.dateRange" }
        require(selection.startDateInclusive == null ||
            !selection.startDateInclusive.isAfter(selection.endDateInclusive)) { "selection.dateRange" }
        require(selection.modeFilter == null ||
            (selection.modeFilter.isNotEmpty() && selection.modeFilter.all { it in MODE_ORDER })) { "selection.modeFilter" }
        require(selection.planFilter == null || selection.planFilter.isNotEmpty()) { "selection.planFilter" }
        require(displayLocale.isNotEmpty()) { "displayLocale" }
        require(generatedAt.nano % 1_000_000 == 0) { "generatedAt" }
        val unknown = selection.includedUnknownDateSessionIds
        require(unknown.size == unknown.toSet().size &&
            selection.includedSessionIds.filter { it in unknown } == unknown) {
            "selection.includedUnknownDateSessionIds"
        }

        json.beginObject().name("trainFlowSessionExport").beginObject()
        json.name("exportContractVersion").value(2L)
        json.string("generatedAt", MILLIS_FORMAT.format(generatedAt))
        json.string("displayLocale", displayLocale)
        json.name("displayContractVersion").value(1L)
        json.name("selection").beginObject()
        json.string("source", selection.source)
        json.string("selectionScope", "user_selected_subset")
        json.nullableString("startDateInclusive", selection.startDateInclusive?.toString())
        json.nullableString("endDateInclusive", selection.endDateInclusive?.toString())
        json.name("modeFilter")
        if (selection.modeFilter == null) json.nullValue() else json.stringArray(MODE_ORDER.filter { it in selection.modeFilter })
        json.name("planFilter")
        if (selection.planFilter == null) json.nullValue() else json.stringArray(selection.planFilter.sorted())
        json.name("includedSessionIds").stringArray(selection.includedSessionIds)
        json.name("includedUnknownDateSessionIds").stringArray(unknown)
        json.endObject()
        json.name("dataDictionary").canonicalValue(EXPORT_DICTIONARY)
        json.name("sessions").beginArray()
    }

    fun writeSession(result: WorkoutSessionStrictReadResult) {
        check(!finished && nextSession < selection.includedSessionIds.size) { "sessions: unexpected write" }
        val requestedId = selection.includedSessionIds[nextSession]
        val session: WorkoutSessionEntity
        val graph: CanonicalSessionGraphV1?
        val execution: StrictSessionExecution
        val planRoot: CanonicalJsonValue.Obj
        when (result) {
            is WorkoutSessionStrictReadResult.CanonicalTerminal -> {
                session = result.graph.session
                graph = result.graph
                execution = result.execution
                planRoot = result.planRoot
            }
            is WorkoutSessionStrictReadResult.LegacyTerminal -> {
                session = result.session
                graph = null
                execution = result.execution
                planRoot = result.planRoot
            }
            else -> throw WorkoutSessionExportReadRejected(requestedId, result)
        }
        check(session.id == requestedId) { "sessions[$nextSession].sessionId" }
        check(selection.modeFilter == null || session.mode in selection.modeFilter) { "sessions[$nextSession].mode" }
        check(selection.planFilter == null || session.planId in selection.planFilter) { "sessions[$nextSession].planId" }
        val unknownDate = session.startLocalDate == null
        check((session.id in selection.includedUnknownDateSessionIds) == unknownDate) {
            "selection.includedUnknownDateSessionIds[$requestedId]"
        }
        if (!unknownDate && selection.startDateInclusive != null) {
            val date = LocalDate.parse(session.startLocalDate)
            check(!date.isBefore(selection.startDateInclusive) && !date.isAfter(selection.endDateInclusive)) {
                "sessions[$nextSession].startLocalDate"
            }
        }
        val historical = resolveWorkoutSessionHistorical(result, displayLocale)
        val resolved = when (historical) {
            is WorkoutSessionHistoricalResult.Resolved -> historical
            else -> throw WorkoutSessionExportHistoricalRejected(requestedId, historical)
        }
        json.beginObject()
        writeSessionHeader(session, planRoot, graph)
        writeExecution(execution, graph, resolved)
        writeHeartRate(graph)
        json.endObject()
        nextSession++
    }

    fun finish() {
        check(!finished && nextSession == selection.includedSessionIds.size) { "sessions: incomplete document" }
        json.endArray().endObject().endObject()
        finished = true
    }

    private fun writeSessionHeader(
        session: WorkoutSessionEntity,
        planRoot: CanonicalJsonValue.Obj,
        graph: CanonicalSessionGraphV1?
    ) {
        json.name("session").beginObject()
        json.string("sessionId", session.id)
        json.nullableString("planId", session.planId)
        json.string("mode", session.mode)
        json.string("terminalStatus", session.status)
        json.string("timelineStatus", if (graph == null) "legacy_incomplete" else "canonical_v1")
        json.nullableNumber("timelineVersion", session.timelineVersion)
        json.nullableNumber("trustedEndOffsetMs", session.trustedEndOffsetMs)
        json.nullableNumber("canonicalSessionDurationMs", session.trustedEndOffsetMs)
        json.nullableString("terminalReason", session.terminalReason)
        json.nullableString("startedAt", session.startedAt)
        json.nullableString("endedAt", session.endedAt)
        json.string("planSnapshotJson", session.planSnapshotJson)
        json.nullableNumber("planSnapshotStorageContractVersion",
            (planRoot.fields["planSnapshotStorageContractVersion"] as? CanonicalJsonValue.Num)?.value)
        json.name("displayMetadata")
        if (graph == null) json.nullValue() else json.canonicalValue(
            parseCanonicalJson(session.sessionDisplayMetadataJson!!)!!
        )
        json.name("timeMetadata").beginObject()
        json.nullableNumber("sourceContractVersion", session.timeMetadataSourceContractVersion)
        json.nullableString("startLocalDate", session.startLocalDate)
        json.nullableString("startZoneId", session.startZoneId)
        json.nullableNumber("startUtcOffsetSeconds", session.startUtcOffsetSeconds)
        json.string("startTimestampBasis", timestampBasis(session.startedAt, session.timeMetadataSourceContractVersion))
        json.string("endTimestampBasis", timestampBasis(session.endedAt, session.timeMetadataSourceContractVersion))
        val trustedEnd = if (session.startedAt != null && session.trustedEndOffsetMs != null) {
            MILLIS_FORMAT.format(Instant.parse(session.startedAt).plusMillis(session.trustedEndOffsetMs))
        } else null
        json.string("trustedEndAtBasis", if (trustedEnd == null) "unavailable" else "start_anchor_plus_trusted_offset")
        json.nullableString("trustedEndAtUtc", trustedEnd)
        json.endObject().endObject()
    }

    private fun writeExecution(
        execution: StrictSessionExecution,
        graph: CanonicalSessionGraphV1?,
        resolved: WorkoutSessionHistoricalResult.Resolved
    ) {
        json.name("execution").beginObject()
        json.name("sessionStepRecords").beginArray()
        for (step in execution.steps) {
            json.beginObject()
            json.string("stepId", step.stepId)
            json.string("kind", step.kind)
            json.nullableString("blockId", step.blockId)
            json.nullableString("itemId", step.itemId)
            json.nullableString("setPlanId", step.setPlanId)
            json.nullableString("exerciseId", step.exerciseId)
            json.string("startedAt", step.startedAt)
            json.nullableString("endedAt", step.endedAt)
            json.name("skipped").value(step.skipped)
            json.nullableNumber("actualDurationSec", step.actualDurationSec)
            json.nullableNumber("plannedDurationSec", step.plannedDurationSec)
            json.endObject()
        }
        json.endArray()
        json.name("phases").beginArray()
        for (phase in graph?.phases.orEmpty()) {
            val identity = parseCanonicalJson(phase.phaseIdentityJson) as CanonicalJsonValue.Obj
            val payload = identity.fields.getValue("payload") as CanonicalJsonValue.Obj
            val freeSession = (identity.fields.getValue("family") as CanonicalJsonValue.Str).value == "follow_along_v1" &&
                (payload.fields.getValue("variant") as CanonicalJsonValue.Str).value == "free_session"
            val display = if (freeSession) HistoricalDisplayV1(displayLocale, "resolved", resolved.title)
                else resolved.phaseDisplays.first { it.sequence == phase.sequence }.display
            json.beginObject()
            json.name("sequence").value(phase.sequence.toLong())
            json.name("startOffsetMs").value(phase.startOffsetMs)
            json.name("endOffsetMs").value(phase.endOffsetMs!!)
            json.name("startMutationSequence").value(phase.startMutationSequence)
            json.name("endMutationSequence").value(phase.endMutationSequence!!)
            json.string("phaseKind", phase.phaseKind)
            json.name("phaseIdentity").canonicalValue(identity)
            json.name("display").beginObject()
            json.name("displayContractVersion").value(display.displayContractVersion.toLong())
            json.string("locale", display.locale)
            json.string("resolutionStatus", display.resolutionStatus)
            json.nullableString("label", display.label)
            json.endObject().endObject()
        }
        json.endArray()
        json.name("timedRestExtensions").beginArray()
        for (rest in execution.restExtensions) {
            json.beginObject()
            json.string("recordId", rest.id)
            json.string("stepId", rest.stepId)
            json.name("stepIndex0").value(rest.stepIndex.toLong())
            json.nullableNumber("roundIndex1", rest.roundIndex)
            json.nullableString("restStageId", rest.restStageId)
            json.string("restStageTitle", rest.restStageTitle)
            json.nullableString("previousStageId", rest.previousStageId)
            json.nullableString("previousStageTitle", rest.previousStageTitle)
            json.name("addedSec").value(rest.addedSec.toLong())
            json.name("plannedRestSec").value(rest.plannedRestSec.toLong())
            json.name("restElapsedBeforeExtensionSec").value(rest.restElapsedBeforeExtensionSec.toLong())
            json.name("extensionAtRemainingSec").value(rest.extensionAtRemainingSec.toLong())
            json.name("cumulativeExtraRestSec").value(rest.cumulativeExtraRestSec.toLong())
            json.name("eventElapsedSec").value(rest.eventElapsedSec.toLong())
            json.endObject()
        }
        json.endArray()
        json.name("strengthSetRecords").beginArray()
        for (item in execution.strengthSets) {
            val row = item.row
            json.beginObject()
            json.string("recordId", row.id)
            json.string("exerciseId", row.exerciseId)
            json.nullableString("sourceSetPlanId", row.sourceSetPlanId)
            json.name("setOrder").value(row.setOrder.toLong())
            json.string("setKind", row.setKind)
            json.nullableString("side", row.side)
            json.name("plannedWeight").weight(item.plannedWeight)
            json.name("plannedRepTarget").repTarget(item.plannedRepTarget)
            json.name("actualWeight").weight(item.actualWeight)
            json.nullableNumber("actualReps", item.actualReps)
            json.nullableNumber("activeDurationSec", row.activeDurationSec)
            json.nullableNumber("actualRestAfterSec", row.actualRestAfterSec)
            json.nullableString("effort", row.effort)
            json.nullableString("substitutedFromExerciseId", row.substitutedFromExerciseId)
            json.endObject()
        }
        json.endArray().endObject()
    }

    private fun writeHeartRate(graph: CanonicalSessionGraphV1?) {
        val recording = graph?.recording
        val snapshot = graph?.snapshots?.singleOrNull()
        val status = StatusProjectionV1.project(recording, snapshot)
        json.name("heartRate").beginObject()
        json.string("status", status)
        json.name("recording")
        if (recording == null) json.nullValue() else writeRecording(recording)
        json.name("intentAndAcquisition").beginArray()
        for (interval in graph?.acquisitions.orEmpty()) {
            json.beginObject()
            json.name("sequence").value(interval.sequence.toLong())
            json.name("startOffsetMs").value(interval.startOffsetMs)
            json.name("endOffsetMs").value(interval.endOffsetMs!!)
            json.name("startMutationSequence").value(interval.startMutationSequence)
            json.name("endMutationSequence").value(interval.endMutationSequence!!)
            json.string("recordingIntent", interval.recordingIntent)
            json.nullableString("intentReason", interval.intentReason)
            json.string("deviceState", interval.deviceState)
            json.nullableString("deviceReason", interval.deviceReason)
            json.endObject()
        }
        json.endArray()
        json.name("samples").beginArray()
        for (sample in graph?.samples.orEmpty()) {
            json.beginObject()
            json.name("offsetMs").value(sample.offsetMs)
            json.name("mutationSequence").value(sample.mutationSequence)
            json.name("sampleSequence").value(sample.sampleSequence)
            json.name("bpm").value(sample.bpm.toLong())
            json.endObject()
        }
        json.endArray()
        json.name("originalAnalysis")
        if (snapshot == null) json.nullValue() else writeAnalysis(snapshot, status)
        json.name("durationAudit")
        if (snapshot == null) json.nullValue() else json.canonicalValue(parseCanonicalJson(snapshot.durationBreakdownJson)!!)
        json.endObject()
    }

    private fun writeRecording(recording: HeartRateRecordingEntity) {
        json.beginObject()
        json.string("recordingId", recording.recordingId)
        json.string("status", recording.status)
        json.name("startedOffsetMs").value(recording.startedOffsetMs)
        json.name("startedMutationSequence").value(recording.startedMutationSequence)
        json.name("endedOffsetMs").value(recording.endedOffsetMs!!)
        json.name("endedMutationSequence").value(recording.endedMutationSequence!!)
        json.name("sourceContractVersion").value(recording.sourceContractVersion.toLong())
        json.string("sourceKind", recording.sourceKind)
        json.name("acquisitionContractVersion").value(recording.acquisitionContractVersion.toLong())
        json.name("parameterSnapshotVersion").value(recording.parameterSnapshotVersion.toLong())
        json.name("originalAnalysisVersion").value(recording.originalAnalysisVersion!!.toLong())
        json.nullableNumber("age", recording.age)
        json.nullableNumber("personalMaxBpm", recording.personalMaxBpm)
        json.nullableNumber("effectiveMaxBpm", recording.effectiveMaxBpm)
        json.nullableString("effectiveMaxSource", recording.effectiveMaxSource)
        json.nullableNumber("alertThresholdBpm", recording.alertThresholdBpm)
        json.name("zoneSnapshot")
        if (recording.zoneSnapshotJson == null) json.nullValue()
        else json.canonicalValue(parseCanonicalJson(recording.zoneSnapshotJson)!!)
        json.endObject()
    }

    private fun writeAnalysis(snapshot: HeartRateAnalysisSnapshotEntity, status: String) {
        json.beginObject()
        json.name("analysisVersion").value(snapshot.analysisVersion.toLong())
        json.string("createdAt", snapshot.createdAt)
        json.name("inputLastMutationSequence").value(snapshot.inputLastMutationSequence)
        json.string("status", status)
        json.string("sampleStatus", snapshot.sampleStatus)
        json.string("coverageStatus", snapshot.coverageStatus)
        json.string("zoneStatus", snapshot.zoneStatus)
        json.name("canonicalSampleCount").value(snapshot.canonicalSampleCount)
        json.name("primaryPointSampleCount").value(snapshot.primaryPointSampleCount)
        json.nullableNumber("eligibleDurationMs", snapshot.eligibleDurationMs)
        json.nullableNumber("coveredDurationMs", snapshot.coveredDurationMs)
        json.nullableNumber("coverageBasisPoints", snapshot.coverageBasisPoints)
        json.nullableNumber("weightedBpmMs", snapshot.weightedBpmMs)
        json.nullableNumber("observedAvgBpm", snapshot.observedAvgBpm)
        json.nullableNumber("observedMaxBpm", snapshot.observedMaxBpm)
        json.nullableNumber("highestOffsetMs", snapshot.highestOffsetMs)
        json.nullableNumber("highestMutationSequence", snapshot.highestMutationSequence)
        json.nullableNumber("highestSampleSequence", snapshot.highestSampleSequence)
        json.name("analysisConfig").canonicalValue(parseCanonicalJson(snapshot.analysisConfigJson)!!)
        json.name("zoneDurations")
        if (snapshot.zoneDurationsJson == null) json.nullValue()
        else json.canonicalValue(parseCanonicalJson(snapshot.zoneDurationsJson)!!)
        json.name("phaseAggregates").canonicalValue(parseCanonicalJson(snapshot.phaseAggregatesJson)!!)
        json.name("qualityReasons").canonicalValue(parseCanonicalJson(snapshot.qualityReasonsJson)!!)
        json.endObject()
    }
}

private val MODE_ORDER = listOf("timed", "strength", "follow_along")
private val MILLIS_FORMAT = DateTimeFormatterBuilder().appendInstant(3).toFormatter()

private fun timestampBasis(timestamp: String?, sourceVersion: Long?): String = when {
    timestamp == null -> "unknown"
    sourceVersion == 1L -> "observed"
    else -> "legacy_stored"
}

private fun JsonWriter.string(name: String, value: String): JsonWriter = name(name).value(value)
private fun JsonWriter.nullableString(name: String, value: String?): JsonWriter =
    name(name).apply { if (value == null) nullValue() else value(value) }
private fun JsonWriter.nullableNumber(name: String, value: Number?): JsonWriter =
    name(name).apply { if (value == null) nullValue() else value(value) }
private fun JsonWriter.stringArray(values: List<String>): JsonWriter = apply {
    beginArray()
    values.forEach { value(it) }
    endArray()
}
private fun JsonWriter.weight(weight: WeightValue?): JsonWriter = apply {
    if (weight == null) nullValue() else {
        beginObject()
        name("value").value(weight.value)
        string("unit", weight.unit.contractValue)
        endObject()
    }
}
private fun JsonWriter.repTarget(target: RepTarget?): JsonWriter = apply {
    when (target) {
        null -> nullValue()
        is RepTarget.Fixed -> {
            beginObject()
            string("kind", "fixed")
            name("reps").value(target.reps.toLong())
            endObject()
        }
        is RepTarget.Range -> {
            beginObject()
            string("kind", "range")
            name("minReps").value(target.minReps.toLong())
            name("maxReps").value(target.maxReps.toLong())
            endObject()
        }
    }
}
private fun JsonWriter.canonicalValue(value: CanonicalJsonValue): JsonWriter = apply {
    when (value) {
        is CanonicalJsonValue.Obj -> {
            beginObject()
            value.fields.forEach { (key, child) -> name(key).canonicalValue(child) }
            endObject()
        }
        is CanonicalJsonValue.Arr -> {
            beginArray()
            value.values.forEach { canonicalValue(it) }
            endArray()
        }
        is CanonicalJsonValue.Str -> value(value.value)
        is CanonicalJsonValue.Num -> value(value.value)
        is CanonicalJsonValue.Bool -> value(value.value)
        CanonicalJsonValue.Null -> nullValue()
    }
}

private val EXPORT_DICTIONARY_JSON: String = listOf(
